"""Single-thread coroutine driver for an offline event tape; no sockets."""
import heapq


class Future:
    def __init__(self):
        self.value = None
        self.error = None
        self.finished = False
        self.listeners = []

    def done(self):
        return self.finished

    def set_result(self, value):
        if self.finished:
            return
        self.finished = True
        self.value = value
        for callback in self.listeners:
            callback(self)
        self.listeners.clear()

    def set_exception(self, error):
        if self.finished:
            return
        self.error = error
        self.set_result(None)

    def __await__(self):
        if not self.finished:
            yield self
        if self.error is not None:
            raise self.error
        return self.value


class Task(Future):
    def __init__(self, clock, coroutine):
        super().__init__()
        self.clock = clock
        self.coroutine = coroutine

    def step(self, previous=None):
        if self.finished:
            return
        try:
            if previous is not None and previous.error is not None:
                wait = self.coroutine.throw(previous.error)
            else:
                wait = self.coroutine.send(None if previous is None else previous.value)
        except StopIteration as stop:
            self.set_result(stop.value)
            return
        except Exception as exc:
            self.set_exception(exc)
            return
        if not isinstance(wait,Future):
            self.set_exception(TypeError('unsupported awaitable'))
            return
        wait.listeners.append(self.step)


class Clock:
    def __init__(self):
        self.now = 0
        self.events = []
        self.sequence = 0

    def create_future(self):
        return Future()

    def schedule(self, time, kind, order, callback):
        if not self.now <= time <= (1 << 63)-1:
            raise ValueError('clock range')
        self.sequence += 1
        heapq.heappush(self.events,(time,kind,order,self.sequence,callback))

    def sleep(self, duration, order):
        f = Future()
        self.schedule(self.now+duration,1,order,lambda:f.set_result(None))
        return f

    def run(self, coroutines, records, dispatch):
        tasks = [Task(self,c) for c in coroutines]
        for index, task in enumerate(tasks):
            self.schedule(0,-1,index,task.step)
        for index, record in enumerate(records):
            self.schedule(record['at'],0,index,lambda r=record:dispatch(r))
        while self.events:
            time,_,_,_,callback = heapq.heappop(self.events)
            self.now = time
            callback()
        if any(not task.done() for task in tasks):
            raise RuntimeError('unfinished offline task')
        for task in tasks:
            if task.error is not None:
                raise task.error
        return [task.value for task in tasks]
